import React, { useEffect, useRef } from "react";
import Header from "../../../Layout/header";
import { useState } from "react";
import TableTitle from "../../Form/TableTitle";
import { apiUrls } from "../../../utils/apiUrls";
import { callAPI } from "../../../utils/apiUtils";
import {
  ApiLoder,
  CustomMessages,
  ErrorMessage,
  HasPermission,
  SuccessMessage,
} from "../../../helpers/common";
import Tab from "../../Form/Tab";
import { GhlSvg, StripeSvg } from "../../../SvgFile/Index";
import InputField from "../../Form/InputField";
import SimpleReactValidator from "simple-react-validator";
import SubmitButton from "../../Form/SubmitButton";
import Stripe from "./Stripe";
import moment from "moment";
import { useLocation } from "react-router-dom";
import Stages from "./Stages";

export default function Index() {
  const [loder, setLoader] = useState(false);
   const [open, setopen] = useState(false);
  const [tabdata, setTabdata] = useState("#pills-overview-tab");
  const [value, setValue] = useState({
    apIkey: "",
    pipelineId: "",
    locationId: "",
    calendarName: "",
    generatedToken: "",
  });
  const simpleValidator = useRef(
    new SimpleReactValidator({ messages: CustomMessages })
  );
  const [, forceUpdate] = useState();
  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const code = searchParams.get("code");
  const TenantlistAPI = async () => {
    setLoader(true);
    try {
      const apiResponse = await callAPI(
        apiUrls.GetGHLConfiguration,
        { code: code },
        "GET"
      );
      setLoader(false);
      if (apiResponse?.data?.isSuccess) {
        setValue(apiResponse?.data?.data);
      } else {
        setValue({});
        
      }
    } catch (error) {
      setLoader(false);
    }
  };
  useEffect(() => {
    TenantlistAPI();
    // eslint-disable-next-line
  }, [code]);

  const GetAccessToken = async () => {
    try {
      await callAPI(apiUrls.GetAccessToken, { code: code }, "GET");
    } catch (error) {}
  };

  useEffect(() => {
    if (code) {
      GetAccessToken();
    }
    // eslint-disable-next-line
  }, [code]);

  const Tablist = [
    HasPermission("GHLView") && {
      status: true,
      id: "#ghl",
      svg: <GhlSvg />,
      title: "GHL Configuration",
    },
    HasPermission("StripeView") && {
      status: false,
      id: "#Stripe",
      svg: <StripeSvg />,
      title: "Stripe Configuration",
    },
    
  ];

  const handleTabchnage = (value) => {
    setTabdata(value || Tablist[0].id);
  };
  const initialActiveTab = localStorage.getItem("activeTab2") || Tablist[0].id;

  const handleChange = (e) => {
    const value = e.target?.value;
    const name = e.target?.name;
    setValue((val) => {
      return { ...val, [name]: value };
    });
  };
  const handleSubmit = async (e) => {
    e.preventDefault();
    const formValid = simpleValidator.current.allValid();
    if (!formValid) {
      simpleValidator.current.showMessages();
      forceUpdate(1);
    } else {
      setLoader(true);
      try {
        const response = await callAPI(
          apiUrls.AddGHLConfiguration,
          {},
          "POST",
          value
        );
        setLoader(false);
        if (response.data.isSuccess) {
          SuccessMessage(response.data?.message);
          TenantlistAPI();
        } else {
          ErrorMessage(response.data.message);
        }
      } catch (error) {
        setLoader(false);
      }
    }
  };

  const handleChnage = async () => {
    const isConfirmed = window.confirm(
      "Are you sure you want to sync Ghl Configuration?"
    );
    if (isConfirmed) {
      setLoader(true);
      try {
        const response = await callAPI(apiUrls.ghlsync, {}, "GET");
        setLoader(false);
        if (response.data.isSuccess) {
          SuccessMessage(response.data.message);
          TenantlistAPI();
        } else {
          ErrorMessage(response.data.message);
        }
      } catch (error) {
        setLoader(false);
      }
    } else {
      setLoader(false);
    }
  };

  const handleChnages = async () => {
    const isConfirmed = window.confirm(
      "Are you sure you want to Generate Token?"
    );
    if (isConfirmed) {
      setLoader(true);
      try {
        const response = await callAPI(apiUrls.GenerateToken, {}, "GET");
        setLoader(false);
        if (response.data.isSuccess) {
          setValue((val) => {
            return { ...val, generatedToken: response?.data?.data };
          });
          SuccessMessage(response.data.message);
        } else {
          ErrorMessage(response.data.message);
        }
      } catch (error) {
        setLoader(false);
      }
    } else {
      setLoader(false);
    }
  };

  const handleChnagess = async () => {
    const isConfirmed = window.confirm("Are you sure you want to go to Link?");
    if (isConfirmed) {
      setLoader(true);
      try {
        const response = await callAPI(
          apiUrls.GoHighLevelAuthorization,
          {},
          "GET"
        );
        setLoader(false);

        if (response.data.isSuccess) {
          window.open(response?.data?.data, "_blank", "noopener,noreferrer");
        } else {
          ErrorMessage(response.data.message);
        }
      } catch (error) {
        setLoader(false);
      }
    } else {
      setLoader(false);
    }
  };

  return (
    <>
      {loder && <ApiLoder />}
      <div className="intersight_content">
        <Header title="Configuration" />
        <div className="body_content">
          <div className="contact-profile">
            <div className="engage-tabs">
              <ul className="nav nav-pills" id="pills-tab" role="tablist">
                <Tab Tablist={Tablist} handleTabchnage={handleTabchnage} />
              </ul>
              <div className="tab-content" id="ghl">
                <div
                  className={`tab-pane fade ${
                    initialActiveTab === "#ghl" ? "show active" : ""
                  }`}
                  id="ghl"
                  role="tabpanel"
                  aria-labelledby="pills-overview-tab"
                  tabIndex={0}
                >
                  
                  <div className="contact-profile">
                    <div className="d-flex align-items-center justify-content-between mb-30">
                      <TableTitle title="Manage GHL Configuration" />
                    </div>
                    <div
                      className="form-design"
                      style={{ background: "#f5f5f5", padding: "10px" }}
                    >
                      <form onSubmit={handleSubmit}>
                        <div className="row">
                          <div className="col-lg-4 col-md-4">
                            <div className="form-group">
                              <InputField
                                labelName={"Api Key"}
                                placeholderName={"Enter Api Key"}
                                type={"text"}
                                handleChange={handleChange}
                                id={"apIkey"}
                                name={"apIkey"}
                                value={value.apIkey}
                                required={true}
                              />
                              <div className="error">
                                {simpleValidator.current.message(
                                  "apIkey",
                                  value?.apIkey,
                                  `required`
                                )}
                              </div>
                            </div>
                          </div>
                          <div className="col-lg-4 col-md-4">
                            <div className="form-group">
                              <InputField
                                labelName={"Pipe line Info"}
                                placeholderName={"Enter Pipe line Info"}
                                type={"text"}
                                handleChange={handleChange}
                                id={"pipelineId"}
                                name={"pipelineId"}
                                value={value.pipelineId}
                                required={true}
                              />
                              <div className="error">
                                {simpleValidator.current.message(
                                  "pipelineInfo",
                                  value?.pipelineId,
                                  `required`
                                )}
                              </div>
                            </div>
                          </div>
                          <div className="col-lg-4 col-md-4">
                            <div className="form-group">
                              <InputField
                                labelName={"Location Id"}
                                placeholderName={"Enter LocationId"}
                                type={"text"}
                                handleChange={handleChange}
                                id={"locationId"}
                                name={"locationId"}
                                value={value.locationId}
                                required={true}
                              />
                              <div className="error">
                                {simpleValidator.current.message(
                                  "Location Id",
                                  value?.locationId,
                                  `required`
                                )}
                              </div>
                            </div>
                          </div>
                          <div className="col-lg-4 col-md-4">
                            <div className="form-group">
                              <InputField
                                labelName={"Calendar Name"}
                                placeholderName={"Enter Calendar Name"}
                                type={"text"}
                                handleChange={handleChange}
                                id={"calendarName"}
                                name={"calendarName"}
                                value={value.calendarName}
                                required={true}
                              />
                              <div className="error">
                                {simpleValidator.current.message(
                                  "Calendar Name",
                                  value?.calendarName,
                                  `required`
                                )}
                              </div>
                            </div>
                          </div>
                          <div className="col-lg-4 col-md-4">
                            <div className="form-group">
                              <InputField
                                labelName={"Generated Token"}
                                placeholderName={"Enter Generated Token"}
                                type={"text"}
                                handleChange={handleChange}
                                id={"generatedToken"}
                                name={"generatedToken"}
                                value={value.generatedToken}
                              />
                            </div>
                          </div>

                          <p>
                            Last Sync :{" "}
                            <strong>
                              {value?.lastSync
                                ? `${moment(value?.lastSync).format(
                                    "MM-DD-YYYY"
                                  )} | ${moment(value?.lastSync).format(
                                    "hh:mm A"
                                  )}`
                                : "N/A"}
                            </strong>
                          </p>
                          {HasPermission("GHLEdit") && (
                            <>
                              <div className="form-group d-flex align-items-center justify-content-end">
                                <SubmitButton
                                  type="submit"
                                  className="btn blue-btn me-2"
                                  name={"Submit"}
                                  disabled={loder}
                                />

                                <button
                                  type="button"
                                  onClick={handleChnage}
                                  className="btn blue-btn me-2"
                                >
                                  Sync GHL
                                </button>

                                <button
                                  type="button"
                                  onClick={handleChnages}
                                  className="btn blue-btn me-2"
                                >
                                  Generate Token
                                </button>
                                <button
                                  type="button"
                                  onClick={handleChnagess}
                                  className="btn blue-btn me-2"
                                >
                                  Link to Ghl
                                </button>
                                <button
                                  type="button"
                                  onClick={(()=>setopen(true))}
                                  className="btn blue-btn"
                                >
                                
                                   GHL Stages Mapping
                                </button>
                               
                              </div>
                            </>
                          )}
                        </div>
                      </form>
                    </div>
                  </div>
                </div>
                {/* vendorlisttab */}

                {HasPermission("StripeView") && (
                  <div
                    className={`tab-pane fade ${
                      initialActiveTab === "#Stripe" ? "show active" : ""
                    }`}
                    id="Stripe"
                    role="tabpanel"
                    aria-labelledby="pills-payment-tab"
                    tabIndex={0}
                  >
                    {tabdata === "#Stripe" && <Stripe />}
                  </div>
                )}

              
              </div>
            </div>
          </div>
        </div>
      </div>
      <Stages open={open} handleclose={(()=>setopen(false))} action={open}/>
    </>
  );
}
